package dev.henrique.inventory.service;
import dev.henrique.inventory.api.ApiModels.ReservationLineRequest; import dev.henrique.inventory.domain.*; import dev.henrique.inventory.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service public class ReservationService { private final ProductRepository products; private final InventoryRepository inventory; private final ReservationRepository reservations; public ReservationService(ProductRepository p,InventoryRepository i,ReservationRepository r){products=p;inventory=i;reservations=r;}
 @Transactional public Reservation create(List<ReservationLineRequest> lines){Map<UUID,Integer> requested=new HashMap<>();for(var l:lines)requested.merge(l.productId(),l.quantity(),Math::addExact);List<UUID> ids=requested.keySet().stream().sorted().toList();Map<UUID,Product> ps=products.findAllById(ids).stream().collect(Collectors.toMap(Product::getId,Function.identity()));for(UUID id:ids)if(!ps.containsKey(id))throw new ResourceNotFoundException("Product not found: "+id);Map<UUID,Inventory> locked=inventory.lockAllByProductIds(ids).stream().collect(Collectors.toMap(Inventory::getProductId,Function.identity()));for(UUID id:ids){Inventory row=locked.get(id);if(row==null)throw new InsufficientInventoryException(id,requested.get(id),0);row.reserve(requested.get(id));}Reservation r=new Reservation();ids.forEach(id->r.addItem(ps.get(id),requested.get(id)));return reservations.save(r);}
 @Transactional public Reservation transition(UUID id,ReservationStatus target){Reservation r=reservations.findById(id).orElseThrow(()->new ResourceNotFoundException("Reservation not found: "+id));if(target==ReservationStatus.CANCELLED||target==ReservationStatus.EXPIRED){List<UUID> ids=r.getItems().stream().map(i->i.getProduct().getId()).sorted().toList();Map<UUID,Inventory> locked=inventory.lockAllByProductIds(ids).stream().collect(Collectors.toMap(Inventory::getProductId,Function.identity()));r.getItems().forEach(i->locked.get(i.getProduct().getId()).release(i.getQuantity()));}r.transitionTo(target);return r;}
 @Transactional(readOnly=true) public Reservation get(UUID id){return reservations.findById(id).orElseThrow(()->new ResourceNotFoundException("Reservation not found: "+id));}
}
